            "Receive your German residence permit (Aufenthaltserlaubnis) from local immigration (Ausländerbehörde).",
            "Register at the town hall (Rathaus) and receive your Meldebestätigung (registration certificate).",
            "Log into your Fintiba/Expatrio app and submit your residence permit + university enrollment documents.",
            "Confirm your monthly withdrawal amount (usually EUR 992, but you can request adjustments).",
            "Set up automatic monthly transfers to your spending account (Girokonto), or withdraw via ATM.",
            "Each month, EUR 992 (or your agreed amount) is deducted from the blocked balance and made available.",
            "When your account balance reaches zero (after ~12 months), it's closed automatically.",
            "If you leave Germany early, the remaining balance is refunded (minus any fees)."
