      "tag": "Applications",
      "date": "2026",
      "title": "How to Email a Professor for MS Admission 2026: Template & Mistakes to Avoid",
      "excerpt": "A concise, copy-ready guide to writing a cold email to a professor that actually gets a reply — what to say, what to avoid, when to send, and a working template.",
      "kw": "how to email professor for ms admission, cold email professor phd, email to professor for research, how to contact professor usa, email professor sample",
      "sections": [
        {
          "h": "Why it matters",
          "body": "A positive reply from a professor who wants you in their lab or seminar can strengthen your application, sometimes trigger internal funding, and shows you have researched the programme. However, most professors ignore generic emails — the difference is specificity and brevity."
        },
        {
          "h": "When to send",
          "body": "For US universities: September–October for a January application, or November–December for a fall intake. Email one professor at a time per school. Avoid holiday windows (late November, December 24–January 1)."
        },
        {
          "h": "The structure that works (4 paragraphs max)",
          "body": "1) Who you are + one specific paper of theirs you read and why it connects to your work. 2) Your background — degree, GPA, one concrete research contribution (paper, project, dataset). 3) What you hope to do in their group — one specific research question. 4) A clear, easy ask: 'I would be grateful to hear whether you are taking students for Fall 2027, and if a brief call to discuss would suit you.' Attach CV, not your full SOP."
        },
        {
          "h": "Subject line",
          "body": "Prospective MS/PhD student — [your area] / [your degree + institution]. E.g.: 'Prospective MS student — NLP for low-resource languages / IIT Bombay'. Specific, scannable, not salesy."
        },
        {
          "h": "What tanks a reply",
          "body": "Generic openers ('I am very interested in your work'), attaching a full SOP, emailing a professor who publishes in a completely different field, asking about funding in the first email, and spelling the professor's name wrong. All are immediately deletable."
        },
        {
          "h": "After you send",
          "body": "One follow-up after 2 weeks is fine; more is not. If there is no reply after two contacts, move on. A non-reply is not a rejection of your application — many professors simply do not manage prospective-student email. Take a free GRE mock on LandingPrep to make sure your test score backs up the application you are pitching."
        }
      ]
